import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { GoogleMap, LoadScript, Marker, DirectionsRenderer } from "@react-google-maps/api";
import { io } from "socket.io-client";
import axios from "axios";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const SOCKET_URL = "http://localhost:5000"; // adjust if different
const GOOGLE_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

interface Location {
  lat: number;
  lng: number;
}

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const mapRef = useRef<google.maps.Map | null>(null);

  const [driverLocation, setDriverLocation] = useState<Location | null>(null);
  const [destination, setDestination] = useState<Location | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);

  useEffect(() => {
    if (!id) return;

    const socket = io(SOCKET_URL);

    socket.emit('trackDelivery', id);

    socket.on('driverLocationUpdate', (location: Location) => {
      setDriverLocation(location);
      if (destination) {
        fetchDirections(location, destination);
      }
    });

    axios.get(`${API_BASE_URL}/api/delivery/${id}`)
      .then(res => {
        const delivery = res.data;
        if (delivery && delivery.location) {
          setDestination(delivery.location);
        }
      })
      .catch(err => {
        console.error("❌ Failed to fetch delivery:", err);
      });

    return () => {
      socket.disconnect();
    };
  }, [id]);

  const fetchDirections = (origin: Location, destination: Location) => {
    const directionsService = new window.google.maps.DirectionsService();
    directionsService.route(
      {
        origin,
        destination,
        travelMode: window.google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === window.google.maps.DirectionsStatus.OK && result) {
          setDirections(result);
        } else {
          console.error("❌ Directions request failed:", status);
        }
      }
    );
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Tracking Delivery</h2>

      <LoadScript googleMapsApiKey={GOOGLE_API_KEY}>
        <GoogleMap
          mapContainerStyle={{ width: "100%", height: "500px" }}
          center={driverLocation || destination || { lat: 6.9271, lng: 79.8612 }}
          zoom={13}
          onLoad={(map) => (mapRef.current = map)}
        >
          {driverLocation && <Marker position={driverLocation} label="Driver" />}
          {destination && <Marker position={destination} label="Destination" />}
          {directions && <DirectionsRenderer directions={directions} />}
        </GoogleMap>
      </LoadScript>

      <div style={{ marginTop: "20px" }}>
        <button
          onClick={() => navigate("/")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#6c757d",
            color: "#fff",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          ← Back to Dashboard
        </button>
      </div>
    </div>
  );
}
